package core

import (
	"fmt"
	"strings"
)

// GlobalConfigName is the generated file (sorting first) holding the
// panel-wide Apache directives.
const GlobalConfigName = "00-panel-global.conf"

// Generator renders Apache config files from the registry. Output is
// deterministic — same registry, byte-identical files — so it can be
// golden-file tested (Plan 10.1). The per-project shape reuses the
// exact directives the M0 spike proved on a real Apache (per-Directory
// FcgidWrapper, no mod_php anywhere, Plan D4/D5).
type Generator struct {
	// TLS, when Enabled, adds the :443 VirtualHost to the global
	// file. Zero value = no vhost (HTTP-only), so existing callers
	// and golden files are unaffected.
	TLS TLSVHost
	// ApacheLogs, when Dir is set, adds the ErrorLog/CustomLog
	// block to the global file (see apache_logs.go). Zero value =
	// no log directives, so diffs and golden files are unaffected.
	ApacheLogs ApacheLogConfig
}

// TLSVHost describes the panel's HTTPS front for Apache: one global
// VirtualHost reusing the server-level Alias/Directory blocks (the
// projects are path-routed under one IP/hostname, so one leaf serves
// them all). Inheritance of server-level Alias/Directory into the
// vhost is the assumption rollout step 4 must prove on Windows;
// the fallback, if proven wrong, is duplicating those blocks into
// the vhost.
type TLSVHost struct {
	Enabled  bool
	Port     int
	CertFile string
	KeyFile  string
}

// GenerateAll renders the global file plus one file per enabled
// project, keyed by file name. Disabled projects generate nothing:
// Apache must not route them at all.
func (g Generator) GenerateAll(reg Registry) (map[string]string, error) {
	if err := reg.ValidateStructure(); err != nil {
		return nil, fmt.Errorf("configgen: %w", err)
	}
	out := map[string]string{GlobalConfigName: g.globalConfig(reg.Settings.Fcgid.Effective())}
	for _, p := range reg.SortedProjects() {
		if !p.Enabled {
			continue
		}
		php, _ := reg.FindPHP(p.PHPVersion)
		out[p.Name+".conf"] = generateProject(reg.Settings.DocumentRoot, p, php)
	}
	return out, nil
}

func (g Generator) globalConfig(f FcgidSettings) string {
	var b strings.Builder
	b.WriteString("# Generated by SPanel+ - DO NOT EDIT. Change projects through the panel/CLI.\n")
	b.WriteString("# Panel-wide directives. The fcgid module itself is loaded by httpd.conf (adoption step);\n")
	b.WriteString("# doctor verifies mod_fcgid is present and matching.\n")
	b.WriteString("# Fcgid values below come from registry settings.fcgid (Fase 2c dashboard);\n")
	b.WriteString("# a registry without them renders the historic defaults.\n\n")
	b.WriteString("<IfModule dir_module>\n")
	b.WriteString("    DirectoryIndex index.php index.html\n")
	b.WriteString("</IfModule>\n\n")
	b.WriteString("<IfModule fcgid_module>\n")
	fmt.Fprintf(&b, "    FcgidMaxProcesses %d\n", f.MaxProcesses)
	fmt.Fprintf(&b, "    FcgidMaxProcessesPerClass %d\n", f.MaxProcessesPerClass)
	fmt.Fprintf(&b, "    FcgidMaxRequestsPerProcess %d\n", f.MaxRequestsPerProcess)
	// Issue #4: the mod_fcgid default MaxRequestLen is 131072 (128 KB),
	// so a 136 KB EMC request failed with 500. 16 MB is the default
	// here; the dashboard may raise it, and the value survives apply
	// because it lives in the registry, not in this file.
	fmt.Fprintf(&b, "    FcgidMaxRequestLen %d\n", f.MaxRequestLen)
	fmt.Fprintf(&b, "    FcgidIOTimeout %d\n", f.IOTimeout)
	fmt.Fprintf(&b, "    FcgidBusyTimeout %d\n", f.BusyTimeout)
	fmt.Fprintf(&b, "    FcgidIdleTimeout %d\n", f.IdleTimeout)
	fmt.Fprintf(&b, "    FcgidInitialEnv PHP_FCGI_MAX_REQUESTS %d\n", f.MaxRequestsPerProcess)
	b.WriteString("    FcgidInitialEnv SystemRoot \"C:/Windows\"\n")
	b.WriteString("    FcgidInitialEnv SystemDrive \"C:\"\n")
	b.WriteString("    FcgidInitialEnv TEMP \"C:/Windows/Temp\"\n")
	b.WriteString("    FcgidInitialEnv TMP \"C:/Windows/Temp\"\n")
	b.WriteString("    FcgidInitialEnv windir \"C:/Windows\"\n")
	b.WriteString("</IfModule>\n")
	b.WriteString(g.apacheLogDirectives())
	if g.TLS.Enabled {
		b.WriteString("\n")
		b.WriteString("# HTTPS (panel TLS): one global VirtualHost reusing the\n")
		b.WriteString("# server-level Alias/Directory blocks above. HTTP projects\n")
		b.WriteString("# stay live in v1 (no forced redirect).\n")
		fmt.Fprintf(&b, "Listen %d\n", g.TLS.Port)
		fmt.Fprintf(&b, "<VirtualHost *:%d>\n", g.TLS.Port)
		b.WriteString("    SSLEngine on\n")
		fmt.Fprintf(&b, "    SSLCertificateFile \"%s\"\n", slashPath(g.TLS.CertFile))
		fmt.Fprintf(&b, "    SSLCertificateKeyFile \"%s\"\n", slashPath(g.TLS.KeyFile))
		b.WriteString("    SSLProtocol -all +TLSv1.2 +TLSv1.3\n")
		b.WriteString("</VirtualHost>\n")
	}
	return b.String()
}

// apacheLogDirectives renders the ErrorLog/CustomLog block for the
// global file, or "" when no log dir is configured. The block lives
// in 00-panel-global.conf, which the IncludeOptional at the end of
// httpd.conf loads last — so these directives override httpd.conf's
// own ErrorLog/CustomLog, and the project vhosts plus the TLS
// vhost inherit them (none of them sets its own logs).
//
// Rotation uses bin/rotatelogs.exe relative to ServerRoot
// (== ApacheHome): one dated file per day, pruned after 90 days by
// the panel. The access format uses the panel_combined nickname
// (identical fields to the standard combined format) so a httpd.conf
// that already defines "combined" cannot collide. When rotatelogs
// is missing the directives fall back to plain files in the same
// dir — unbounded, and the comment says so.
func (g Generator) apacheLogDirectives() string {
	cfg := g.ApacheLogs
	if cfg.Dir == "" {
		return ""
	}
	var b strings.Builder
	b.WriteString("\n")
	if cfg.Rotate {
		b.WriteString("# Apache logs (panel): access + error, dirotasi harian\n")
		b.WriteString("# oleh rotatelogs bawaan Apache, disimpan maksimal 90 hari\n")
		b.WriteString("# (3 bulan); file lebih lama dihapus otomatis oleh panel.\n")
		fmt.Fprintf(&b, "# File: %s/access-YYYY-MM-DD.log dan error-YYYY-MM-DD.log.\n", cfg.Dir)
	} else {
		b.WriteString("# Apache logs (panel): rotatelogs.exe tidak ditemukan di\n")
		b.WriteString("# bin/ Apache, jadi log ditulis ke file tunggal tanpa\n")
		b.WriteString("# rotasi harian (retensi 90 hari tidak berlaku untuk file\n")
		b.WriteString("# ini). Pasang rotatelogs dari distribusi Apache untuk\n")
		b.WriteString("# mengaktifkan rotasi harian.\n")
	}
	b.WriteString("# Format access memakai nickname panel_combined (isi sama\n")
	b.WriteString("# dengan format combined standar) supaya tidak bentrok\n")
	b.WriteString("# bila httpd.conf sudah mendefinisikan \"combined\".\n")
	b.WriteString("LogFormat \"%h %l %u %t \\\"%r\\\" %>s %b \\\"%{Referer}i\\\" \\\"%{User-Agent}i\\\"\" panel_combined\n")
	if cfg.Rotate {
		fmt.Fprintf(&b, "ErrorLog \"|bin/rotatelogs.exe %s 86400\"\n", pipeArg(cfg.Dir+"/error-%Y-%m-%d.log"))
		fmt.Fprintf(&b, "CustomLog \"|bin/rotatelogs.exe %s 86400\" panel_combined\n", pipeArg(cfg.Dir+"/access-%Y-%m-%d.log"))
	} else {
		fmt.Fprintf(&b, "ErrorLog %s\n", apacheQuote(cfg.Dir+"/error.log"))
		fmt.Fprintf(&b, "CustomLog %s panel_combined\n", apacheQuote(cfg.Dir+"/access.log"))
	}
	return b.String()
}

// apacheQuote quotes an Apache config path when it contains a space
// (or a quote); plain paths are left unquoted.
func apacheQuote(p string) string {
	if strings.ContainsAny(p, " \t\"") {
		return "\"" + strings.ReplaceAll(p, "\"", "\\\"") + "\""
	}
	return p
}

// pipeArg quotes a path argument inside a piped-log command string:
// the outer command is already double-quoted, so an inner quote
// must be backslash-escaped for Apache's config parser.
func pipeArg(p string) string {
	if strings.ContainsAny(p, " \t\"") {
		return "\\\"" + strings.ReplaceAll(p, "\"", "\\\"") + "\\\""
	}
	return p
}

func generateProject(documentRoot string, p Project, php PHPVersion) string {
	target := slashPath(p.TargetDir())
	var b strings.Builder
	fmt.Fprintf(&b, "# Generated by SPanel+ - DO NOT EDIT. Project: %s (%s)\n", p.Name, p.Type)
	if p.Type != ProjectStatic {
		fmt.Fprintf(&b, "# PHP: %s (%s)\n", php.Version, slashPath(php.Path))
	}
	b.WriteString("\n")

	// An Alias is needed whenever the URL path does not naturally map
	// onto the target dir under the DocumentRoot. For Laravel that is
	// always the case — the Alias to public/ is exactly what removes
	// /public from the URL and keeps the project root (with .env)
	// off the web (Plan D5).
	if needsAlias(documentRoot, p, target) {
		fmt.Fprintf(&b, "Alias \"%s\" \"%s\"\n", p.URLPath, target)
	}
	fmt.Fprintf(&b, "<Directory \"%s\">\n", target)
	if p.Type == ProjectStatic {
		b.WriteString("    AllowOverride None\n")
	} else {
		b.WriteString("    Options +ExecCGI\n")
		b.WriteString("    AllowOverride All\n")
	}
	b.WriteString("    Require all granted\n")
	if p.Type != ProjectStatic {
		b.WriteString("    <FilesMatch \"\\.php$\">\n")
		b.WriteString("        SetHandler fcgid-script\n")
		b.WriteString("    </FilesMatch>\n")
		fmt.Fprintf(&b, "    FcgidWrapper \"%s/php-cgi.exe\" .php\n", slashPath(php.Path))
	}
	b.WriteString("</Directory>\n")
	return b.String()
}

// needsAlias reports whether url_path -> target needs an explicit
// Alias, i.e. the target is not exactly DocumentRoot+url_path.
func needsAlias(documentRoot string, p Project, targetSlash string) bool {
	if p.Type == ProjectLaravel || p.Type == ProjectCI4 {
		return true
	}
	if documentRoot == "" {
		return true
	}
	return slashPath(documentRoot)+p.URLPath != targetSlash
}

// slashPath normalizes a Windows path for Apache config use:
// forward slashes, no trailing slash.
func slashPath(p string) string {
	return strings.TrimRight(strings.ReplaceAll(p, "\\", "/"), "/")
}
